PAYLOAD_SHA256 = '0bb74b29d544d01897621dd4296e77f56830e244ddceb26f2032f411119cc63c'

def main():
    raw = zlib.decompress(base64.b85decode(PAYLOAD))
    if hashlib.sha256(raw).hexdigest() != PAYLOAD_SHA256:
        raise SystemExit('FTI_TELEGRAM_RELEASE_DIGEST_MISMATCH')
    files = json.loads(raw)
    allowed = {'tools/telegram-publisher.py', 'tools/install-telegram-publisher.py', 'config/telegram-launch-posts.en.json'}
    if set(files) != allowed:
        raise SystemExit('FTI_TELEGRAM_RELEASE_PATH_MISMATCH')
    with tempfile.TemporaryDirectory(prefix='fti-telegram-release-') as name:
        root = Path(name)
        for relative, encoded in files.items():
            target = root / relative
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(base64.b64decode(encoded, validate=True))
            target.chmod(0o600)
        runpy.run_path(str(root / 'tools/install-telegram-publisher.py'), run_name='__main__')

if __name__ == '__main__':
    main()
